-- بنك الأسئلة — الكيمياء، الصف التاسع، الوحدة الثانية: 45 سؤالًا (15 لكل درس)، اختيار من متعدد، نصف نقطة لكل سؤال.
-- معلم الكيمياء الأصلي (teacher_id 1)، المادة chemistry (subject_id 2). ظاهرة للطلاب، والحل مخفي (التصحيح على الخادم).
-- لا يُضاف سؤال إن وُجد سؤال بالعنوان نفسه (آمن عند التكرار).
begin;
do $$ begin
  if not exists (select 1 from public.teacher_users where id = 1 and is_active)
     or (select code from public.subjects where id = 2) is distinct from 'chemistry' then
    raise exception 'qb_unit2: teacher 1 / chemistry not as expected';
  end if;
end $$;
insert into public.portal_mt_question_bank(teacher_id, subject_id, title, question_text, question_image, solution_text, solution_image, target_class, is_visible, show_solution)
select 1, 2, v.title, v.q, null, v.sol, null, 'ALL', true, false
from (values
('الذرات والجزيئات | 01 - العنصر','العنصر (Element) هو:','__QB4____العنصر مادة نقية لا يمكن تجزئتها كيميائيًا إلى مواد أبسط منها، وهو «لبنة البناء» التي تتكوّن منها كل المواد.'),
('الذرات والجزيئات | 02 - المركب','المركّب (Compound) هو:','__QB4____المركّب مادة نقية تتكوّن من عنصرين أو أكثر مترابطة معًا كيميائيًا، مثل الماء H₂O.'),
('الذرات والجزيئات | 03 - المواد النقية','النوعان الرئيسيان من المواد النقية هما:','__QB4____المواد النقية نوعان: العناصر والمركّبات. أما المخاليط فتتكوّن من أكثر من مادة.'),
('الذرات والجزيئات | 04 - جزيء الماء','يتكوّن جزيء الماء (H₂O) من:','__QB4____يتكوّن جزيء الماء من ذرتي هيدروجين مرتبطتين بذرة أكسجين واحدة، وصيغته H₂O.'),
('الذرات والجزيئات | 05 - جزيء الميثان','يتكوّن جزيء الميثان (CH₄) من:','__QB4____الميثان CH₄ مركّب يتكوّن جزيئه من ذرة كربون واحدة مرتبطة بأربع ذرات هيدروجين.'),
('الذرات والجزيئات | 06 - جزيئات العناصر','أيّ مما يأتي جزيء لعنصر وليس جزيئًا لمركّب؟','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjMsIm9wdGlvbnMiOlsiSOKCgk8iLCJIQ2wiLCJDSOKChCIsIk/igoIiXX0sInBvaW50cyI6MC41LCJsZXNzb25OYW1lIjoi2KfZhNiw2LHYp9iqINmI2KfZhNis2LLZitim2KfYqiJ9__يتكوّن جزيء الأكسجين O₂ من ذرتين من العنصر نفسه، فهو جزيء عنصر. أما H₂O وHCl وCH₄ فمركّبات من أكثر من عنصر.'),
('الذرات والجزيئات | 07 - المخلوط','يحتوي المخلوط على:','__QB4____يحتوي المخلوط على أكثر من مادة لا تكون ذراتها مترابطة كيميائيًا، ويمكن فصل مكوّناته بتقنيات الفصل الفيزيائية.'),
('الذرات والجزيئات | 08 - المخلوط والمركب','إحدى العبارات الآتية صحيحة عن المركّب وليست عن المخلوط:','__QB4____خصائص المركّب الجديد تختلف عن خصائص العناصر المكوّنة له، ونسب عناصره ثابتة، ولا يمكن فصلها بالطرائق الفيزيائية البسيطة.'),
('الذرات والجزيئات | 09 - التغير الكيميائي','من خصائص التغيّر (التفاعل) الكيميائي:','__QB4____في التفاعل الكيميائي تتكوّن مادة جديدة، ولا يكون سهلًا إرجاع المادة إلى حالتها الأصلية، وقد يكون ماصًا للحرارة أو طاردًا لها.'),
('الذرات والجزيئات | 10 - التغير الفيزيائي','أيّ مما يأتي تغيّر فيزيائي؟','__QB4____ذوبان السكّر تغيّر فيزيائي، لأنه يمكن استعادة بلّورات السكّر بتبخير الماء. أما الاحتراق والتفكّك فتغيّرات كيميائية.'),
('الذرات والجزيئات | 11 - التفكك','عند تسخين كربونات النحاس (II) الخضراء تتحوّل إلى مسحوق أسود ويتصاعد غاز ثاني أكسيد الكربون. يُسمّى هذا النوع من التفاعلات:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjEsIm9wdGlvbnMiOlsi2KfZhNiq2YPZiNmK2YYiLCLYp9mE2KrZgdmD2ZHZgyIsItin2YTYp9mG2LXZh9in2LEiLCLYp9mE2KrZgti32YrYsSJdfSwicG9pbnRzIjowLjUsImxlc3Nvbk5hbWUiOiLYp9mE2LDYsdin2Kog2YjYp9mE2KzYstmK2KbYp9iqIn0=__التفكّك تفاعل يتجزّأ فيه المركّب ليشكّل مادتين أو أكثر: كربونات النحاس (II) ← أكسيد النحاس (II) + ثاني أكسيد الكربون.'),
('الذرات والجزيئات | 12 - التكوين','احتراق الماغنيسيوم في الأكسجين لإنتاج أكسيد الماغنيسيوم مثال على تفاعل:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjAsIm9wdGlvbnMiOlsi2KfZhNiq2YPZiNmK2YYiLCLYp9mE2KrZgdmD2ZHZgyIsItin2YTYqtit2YTZitmEINin2YTZg9mH2LHYqNin2KbZiiIsItin2YTYsNmI2KjYp9mGIl19LCJwb2ludHMiOjAuNSwibGVzc29uTmFtZSI6Itin2YTYsNix2KfYqiDZiNin2YTYrNiy2YrYptin2KoifQ==__التكوين يحدث عندما تتشكّل مادة نتيجة اندماج مادتين أو أكثر: الماغنيسيوم + الأكسجين ← أكسيد الماغنيسيوم.'),
('الذرات والجزيئات | 13 - تفكك بالكهرباء','عند مرور تيار كهربائي في بروميد الرصاص (II) المصهور، ينتج:','__QB4____يتفكّك بروميد الرصاص (II) المصهور بالكهرباء إلى فلز الرصاص (فضي رمادي) وغاز البروم (بني اللون)، ولا يمكن تجزئة أيّ منهما كيميائيًا.'),
('الذرات والجزيئات | 14 - الحديد والكبريت','عند تسخين مخلوط مسحوقي الحديد والكبريت تنتج مادة سوداء صلبة لا تنجذب للمغناطيس هي:','__QB4____يتفاعل الحديد مع الكبريت ليكوّنا مركّبًا جديدًا هو كبريتيد الحديد (II)، وخصائصه تختلف عن الحديد (الذي ينجذب للمغناطيس) وعن الكبريت.'),
('الذرات والجزيئات | 15 - مكونات الكون','العنصران الأساسيان المكوّنان لكتلة الكون هما:','__QB4____يُعتبر الهيدروجين (نحو 92%) والهيليوم (نحو 7%) العنصرين الأساسيين المكوّنين لكتلة الكون.'),
('تركيب الذرة | 01 - دالتون','اعتقد العالم دالتون أن الذرّة:','__QB4____اعتقد دالتون أن الذرات جسيمات صلبة غير قابلة للتجزئة، ثم بيّنت الأبحاث أنها تتكوّن من جسيمات دون ذرية.'),
('تركيب الذرة | 02 - اكتشاف الإلكترون','العالم الذي اكتشف الإلكترون عام 1897م هو:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjAsIm9wdGlvbnMiOlsi2LfZiNmF2LPZiNmGIiwi2LHYsNix2YHZiNix2K8iLCLYtNin2K/ZiNmK2YMiLCLYr9in2YTYqtmI2YYiXX0sInBvaW50cyI6MC41LCJsZXNzb25OYW1lIjoi2KrYsdmD2YrYqCDYp9mE2LDYsdipIn0=__اكتشف طومسون الإلكترون عام 1897م، واكتشف رذرفورد البروتون عام 1913م، واكتُشف النيوترون عام 1932م.'),
('تركيب الذرة | 03 - تجارب رذرفورد','بيّنت تجارب رذرفورد أن الذرّة:','__QB4____استنتج رذرفورد أن الذرّة في معظمها حيّز فارغ تتحرك فيه الإلكترونات السالبة حول نواة صغيرة جدًا موجبة الشحنة تحتوي معظم كتلة الذرّة.'),
('تركيب الذرة | 04 - آخر جسيم','آخر الجسيمات دون الذرّية اكتشافًا (عام 1932م) هو:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjMsIm9wdGlvbnMiOlsi2KfZhNil2YTZg9iq2LHZiNmGIiwi2KfZhNio2LHZiNiq2YjZhiIsItin2YTZhtmI2KfYqSIsItin2YTZhtmK2YjYqtix2YjZhiJdfSwicG9pbnRzIjowLjUsImxlc3Nvbk5hbWUiOiLYqtix2YPZitioINin2YTYsNix2KkifQ==__اكتُشف النيوترون عام 1932م، وكان آخر الجسيمات دون الذرّية اكتشافًا لأنه متعادل الشحنة.'),
('تركيب الذرة | 05 - شحنة النيوترون','الجسيم دون الذرّي المتعادل كهربائيًا (لا يحمل شحنة) هو:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjAsIm9wdGlvbnMiOlsi2KfZhNmG2YrZiNiq2LHZiNmGIiwi2KfZhNio2LHZiNiq2YjZhiIsItin2YTYpdmE2YPYqtix2YjZhiIsItin2YTZhtmI2KfYqSJdfSwicG9pbnRzIjowLjUsImxlc3Nvbk5hbWUiOiLYqtix2YPZitioINin2YTYsNix2KkifQ==__البروتون شحنته +1 والإلكترون −1، أما النيوترون فمتعادل كهربائيًا (شحنته 0).'),
('تركيب الذرة | 06 - كتلة الإلكترون','الكتلة النسبية للإلكترون تساوي تقريبًا:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjEsIm9wdGlvbnMiOlsiMSIsIjEvMTgzNiIsIjIiLCIxODM2Il19LCJwb2ludHMiOjAuNSwibGVzc29uTmFtZSI6Itiq2LHZg9mK2Kgg2KfZhNiw2LHYqSJ9__كتلة الإلكترون ضئيلة جدًا، تساوي تقريبًا 1/1836 من كتلة البروتون، لذلك تتركّز كتلة الذرّة في النواة.'),
('تركيب الذرة | 07 - موقع الجسيمات','يوجد البروتون والنيوترون في:','__QB4____البروتونات والنيوترونات داخل النواة، أما الإلكترونات فتدور حول النواة في مستويات الطاقة.'),
('تركيب الذرة | 08 - الذرة المتعادلة','تكون الذرّة المفردة متعادلة كهربائيًا لأن:','__QB4____الشحنة الموجبة الكلية للنواة (البروتونات) تتعادل مع الشحنة السالبة الكلية للإلكترونات، لأن عدديهما متساويان.'),
('تركيب الذرة | 09 - العدد الذري','العدد الذرّي (Z) هو:','__QB4____العدد الذرّي (Z) هو عدد البروتونات في نواة الذرّة، وهو الذي يحدّد ماهية العنصر.'),
('تركيب الذرة | 10 - العدد الكتلي','العدد الكتلي (A) هو:','__QB4____العدد الكتلي (A) = عدد البروتونات + عدد النيوترونات، أي العدد الكلّي للجسيمات في النواة.'),
('تركيب الذرة | 11 - حساب النيوترونات','ذرّة صوديوم عددها الذرّي 11 وعددها الكتلي 23. عدد النيوترونات في نواتها:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjEsIm9wdGlvbnMiOlsiMTEiLCIxMiIsIjIzIiwiMzQiXX0sInBvaW50cyI6MC41LCJsZXNzb25OYW1lIjoi2KrYsdmD2YrYqCDYp9mE2LDYsdipIn0=__عدد النيوترونات = العدد الكتلي − العدد الذرّي = 23 − 11 = 12 نيوترونًا.'),
('تركيب الذرة | 12 - ذرة الفوسفور','ذرّة فوسفور عددها الذرّي 15 وعددها الكتلي 31. عدد البروتونات والنيوترونات والإلكترونات فيها على الترتيب:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjMsIm9wdGlvbnMiOlsiMTXYjCAxNdiMIDE2IiwiMzHYjCAxNdiMIDE1IiwiMTbYjCAxNdiMIDE1IiwiMTXYjCAxNtiMIDE1Il19LCJwb2ludHMiOjAuNSwibGVzc29uTmFtZSI6Itiq2LHZg9mK2Kgg2KfZhNiw2LHYqSJ9__البروتونات = 15 (العدد الذرّي)، النيوترونات = 31 − 15 = 16، والإلكترونات = 15 لأن الذرّة متعادلة.'),
('تركيب الذرة | 13 - النظائر','النظائر هي ذرّات للعنصر نفسه:','__QB4____النظائر ذرّات للعنصر نفسه تملك العدد الذرّي نفسه (العدد نفسه من البروتونات والإلكترونات) لكنها تختلف في عدد النيوترونات، فيختلف العدد الكتلي.'),
('تركيب الذرة | 14 - الكلور','الفرق بين ذرّة الكلور−35 وذرّة الكلور−37 أن ذرّة الكلور−37 تحتوي على:','__QB4____لكلتا الذرّتين 17 بروتونًا و17 إلكترونًا، لكن الكلور−35 فيه 18 نيوترونًا والكلور−37 فيه 20 نيوترونًا.'),
('تركيب الذرة | 15 - خصائص النظائر','تمتلك نظائر العنصر الواحد الخصائص الكيميائية نفسها لأن:','__QB4____عدد الإلكترونات (وخاصة إلكترونات المستوى الخارجي) هو الذي يتحكّم في التغيّرات الكيميائية، والنظائر لها العدد نفسه من الإلكترونات.'),
('ترتيب الإلكترونات في الذرات | 01 - نظرية بور','النظرية التي فسّرت كيفية ترتيب الإلكترونات في مستويات طاقة حول النواة طوّرها عام 1913م العالم:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjEsIm9wdGlvbnMiOlsi2LfZiNmF2LPZiNmGIiwi2YbZitmE2LIg2KjZiNixIiwi2K/Yp9mE2KrZiNmGIiwi2LHYsNix2YHZiNix2K8iXX0sInBvaW50cyI6MC41LCJsZXNzb25OYW1lIjoi2KrYsdiq2YrYqCDYp9mE2KXZhNmD2KrYsdmI2YbYp9iqINmB2Yog2KfZhNiw2LHYp9iqIn0=__طوّر العالم نيلز بور عام 1913م نظرية تفسّر ترتيب الإلكترونات في الذرّات ضمن مستويات طاقة مختلفة.'),
('ترتيب الإلكترونات في الذرات | 02 - المستوى الأول','العدد الأقصى للإلكترونات التي يستوعبها مستوى الطاقة الأول:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjAsIm9wdGlvbnMiOlsiMiIsIjgiLCIxOCIsIjEiXX0sInBvaW50cyI6MC41LCJsZXNzb25OYW1lIjoi2KrYsdiq2YrYqCDYp9mE2KXZhNmD2KrYsdmI2YbYp9iqINmB2Yog2KfZhNiw2LHYp9iqIn0=__يستوعب مستوى الطاقة الأول إلكترونين اثنين فقط.'),
('ترتيب الإلكترونات في الذرات | 03 - المستوى الثاني','العدد الأقصى للإلكترونات التي يستوعبها مستوى الطاقة الثاني:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjIsIm9wdGlvbnMiOlsiMiIsIjQiLCI4IiwiNiJdfSwicG9pbnRzIjowLjUsImxlc3Nvbk5hbWUiOiLYqtix2KrZitioINin2YTYpdmE2YPYqtix2YjZhtin2Kog2YHZiiDYp9mE2LDYsdin2KoifQ==__يستوعب مستوى الطاقة الثاني ثمانية إلكترونات.'),
('ترتيب الإلكترونات في الذرات | 04 - ملء المستويات','تُملأ مستويات الطاقة بالإلكترونات بدءًا من:','__QB4____يتم ملء مستويات الطاقة بدءًا بالمستوى ذي الطاقة الدنيا، وهو الأقرب إلى النواة.'),
('ترتيب الإلكترونات في الذرات | 05 - طاقة المستويات','أيّ العبارات الآتية صحيحة عن مستويات الطاقة؟','__QB4____تتحرك الإلكترونات في مدارات حول النواة تُسمّى مستويات طاقة، والمستويات البعيدة عن النواة تمتلك طاقات أعلى.'),
('ترتيب الإلكترونات في الذرات | 06 - الكربون','التركيب الإلكتروني لذرّة الكربون (العدد الذرّي 6):','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjEsIm9wdGlvbnMiOlsiMtiMMtiMMiIsIjLYjDQiLCI02IwyIiwiMtiMONiMNiJdfSwicG9pbnRzIjowLjUsImxlc3Nvbk5hbWUiOiLYqtix2KrZitioINin2YTYpdmE2YPYqtix2YjZhtin2Kog2YHZiiDYp9mE2LDYsdin2KoifQ==__عدد الإلكترونات 6: إلكترونان في المستوى الأول، و4 في المستوى الثاني، فيُكتب 2،4.'),
('ترتيب الإلكترونات في الذرات | 07 - الصوديوم','التركيب الإلكتروني لذرّة الصوديوم (العدد الذرّي 11):','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjIsIm9wdGlvbnMiOlsiMtiMOSIsIjLYjDjYjDIiLCIy2Iw42IwxIiwiONiMMtiMMSJdfSwicG9pbnRzIjowLjUsImxlc3Nvbk5hbWUiOiLYqtix2KrZitioINin2YTYpdmE2YPYqtix2YjZhtin2Kog2YHZiiDYp9mE2LDYsdin2KoifQ==__11 إلكترونًا: 2 في المستوى الأول، و8 في الثاني، و1 في الثالث، فيُكتب 2،8،1.'),
('ترتيب الإلكترونات في الذرات | 08 - الكالسيوم','التركيب الإلكتروني لذرّة الكالسيوم (العدد الذرّي 20):','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjMsIm9wdGlvbnMiOlsiMtiMONiMMTAiLCIy2Iw42Iw42IwxIiwiMtiMMTDYjDgiLCIy2Iw42Iw42IwyIl19LCJwb2ludHMiOjAuNSwibGVzc29uTmFtZSI6Itiq2LHYqtmK2Kgg2KfZhNil2YTZg9iq2LHZiNmG2KfYqiDZgdmKINin2YTYsNix2KfYqiJ9__20 إلكترونًا: 2، ثم 8، ثم 8، ويبقى إلكترونان في المستوى الرابع، فيُكتب 2،8،8،2.'),
('ترتيب الإلكترونات في الذرات | 09 - الكلور','التركيب الإلكتروني لذرّة الكلور (العدد الذرّي 17):','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjAsIm9wdGlvbnMiOlsiMtiMONiMNyIsIjLYjDfYjDgiLCIy2Iw42Iw4IiwiONiMONiMMSJdfSwicG9pbnRzIjowLjUsImxlc3Nvbk5hbWUiOiLYqtix2KrZitioINin2YTYpdmE2YPYqtix2YjZhtin2Kog2YHZiiDYp9mE2LDYsdin2KoifQ==__17 إلكترونًا: 2 في المستوى الأول، و8 في الثاني، و7 في الثالث، فيُكتب 2،8،7.'),
('ترتيب الإلكترونات في الذرات | 10 - التركيب 2،8،4','عنصر تركيبه الإلكتروني (2،8،4)، عدده الذرّي:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjEsIm9wdGlvbnMiOlsiNCIsIjE0IiwiMTIiLCIxMCJdfSwicG9pbnRzIjowLjUsImxlc3Nvbk5hbWUiOiLYqtix2KrZitioINin2YTYpdmE2YPYqtix2YjZhtin2Kog2YHZiiDYp9mE2LDYsdin2KoifQ==__العدد الذرّي يساوي مجموع الإلكترونات في الذرّة المتعادلة: 2 + 8 + 4 = 14، وهو عنصر السيليكون.'),
('ترتيب الإلكترونات في الذرات | 11 - النيون','عدد الإلكترونات في مستوى الطاقة الخارجي لذرّة النيون (العدد الذرّي 10):','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjIsIm9wdGlvbnMiOlsiMiIsIjEwIiwiOCIsIjEiXX0sInBvaW50cyI6MC41LCJsZXNzb25OYW1lIjoi2KrYsdiq2YrYqCDYp9mE2KXZhNmD2KrYsdmI2YbYp9iqINmB2Yog2KfZhNiw2LHYp9iqIn0=__تركيب النيون 2،8، فمستواه الخارجي مكتمل بثمانية إلكترونات، وهو ترتيب مستقر كما في الغازات النبيلة.'),
('ترتيب الإلكترونات في الذرات | 12 - البوتاسيوم','التركيب الإلكتروني لذرّة البوتاسيوم (العدد الذرّي 19):','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjMsIm9wdGlvbnMiOlsiMtiMONiMOSIsIjLYjDnYjDgiLCIy2Iw42Iw42IwyIiwiMtiMONiMONiMMSJdfSwicG9pbnRzIjowLjUsImxlc3Nvbk5hbWUiOiLYqtix2KrZitioINin2YTYpdmE2YPYqtix2YjZhtin2Kog2YHZiiDYp9mE2LDYsdin2KoifQ==__19 إلكترونًا: 2، ثم 8، ثم 8، ويبقى إلكترون واحد في المستوى الرابع، فيُكتب 2،8،8،1.'),
('ترتيب الإلكترونات في الذرات | 13 - نظائر الكربون','عدد الإلكترونات في ذرّة الكربون−12 وفي ذرّة الكربون−14 على الترتيب:','__QB4__eyJ2Ijo0LCJ0eXBlIjoibWNxIiwiYW5zd2VyIjp7ImNvcnJlY3QiOjAsIm9wdGlvbnMiOlsiNiDZiDYiLCIxMiDZiDE0IiwiNiDZiDgiLCI2INmIMTQiXX0sInBvaW50cyI6MC41LCJsZXNzb25OYW1lIjoi2KrYsdiq2YrYqCDYp9mE2KXZhNmD2KrYsdmI2YbYp9iqINmB2Yog2KfZhNiw2LHYp9iqIn0=__النظيران للعنصر نفسه، فلهما العدد الذرّي نفسه (6)، وبالتالي العدد نفسه من الإلكترونات (6)، ويختلفان في عدد النيوترونات فقط.'),
('ترتيب الإلكترونات في الذرات | 14 - الترتيب المستقر','يُوصف ترتيب الإلكترونات بأنه مستقر (كما في الغازات النبيلة) عندما:','__QB4____المستوى الثاني والمستويات التي تليه تستوعب ثمانية إلكترونات (أو أكثر) لتصل إلى الترتيب المستقر للإلكترونات كما في الغازات النبيلة.'),
('ترتيب الإلكترونات في الذرات | 15 - الشفق القطبي','تنتج ألوان الشفق القطبي وألوان الألعاب النارية من:','__QB4____تنتج هذه الألوان من حركة الإلكترونات الموجودة في الذرّة، والتي تنتقل بين مستويات طاقة مختلفة.')
) as v(title, q, sol)
where not exists (select 1 from public.portal_mt_question_bank x where x.teacher_id = 1 and x.subject_id = 2 and x.title = v.title);
